SELECT * FROM (SELECT * FROM (SELECT 'TX:' || t.transaction_id event_id, t.warehouse_number case_id, 'Goods Received' activity, t.occurred_at timestamp FROM transaction_record t WHERE t.transaction_type='IN' UNION ALL SELECT 'TX:' || t.transaction_id event_id, t.warehouse_number case_id, 'Goods Dispatched' activity, t.occurred_at timestamp FROM transaction_record t WHERE t.transaction_type='OUT') UNION ALL SELECT e.event_id,l.case_id,e.activity,e.timestamp FROM (SELECT event_id,activity,occurred_at timestamp FROM transaction_record_activity UNION ALL SELECT 'LC:transaction_record:' || transaction_id || ':1' event_id, 'Receiving Requested' activity, receiving_requested_at timestamp FROM transaction_record WHERE receiving_requested_at IS NOT NULL UNION ALL SELECT 'LC:transaction_record:' || transaction_id || ':2' event_id, 'Receiving Scheduled' activity, receiving_scheduled_at timestamp FROM transaction_record WHERE receiving_scheduled_at IS NOT NULL UNION ALL SELECT 'LC:transaction_record:' || transaction_id || ':1' event_id, 'Dispatch Requested' activity, dispatch_requested_at timestamp FROM transaction_record WHERE dispatch_requested_at IS NOT NULL UNION ALL SELECT 'LC:transaction_record:' || transaction_id || ':2' event_id, 'Dispatch Approved' activity, dispatch_approved_at timestamp FROM transaction_record WHERE dispatch_approved_at IS NOT NULL) e JOIN lifecycle_case_link l ON l.event_id=e.event_id WHERE l.case_table='warehouse') ORDER BY case_id,timestamp,event_id;
